    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor tight fits (lower post_residual is better)
    // We use a quadratic term for the post_residual to heavily penalize large gaps
    let mut score = post * post * 0.01;

    // Lookahead interaction: If the next item fits into the current post_residual,
    // we reward this bin heavily to create "perfect" pairs.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= (next_item_size as f64) * 5.0;
    }

    // Progression coupling: As the stream nears completion, become more aggressive 
    // about using open bins rather than opening new ones.
    // If this is a new bin (bin_residual == bin_capacity), penalize it increasingly 
    // as we progress through the stream.
    if bin_residual == bin_capacity {
        score += 15.0 + (progress * 50.0);
    } else {
        // If the bin is already open, apply a non-linear penalty for fragmentation
        // based on the deviation from the mean_residual of other open bins.
        let fragmentation = (post - mean_residual).abs();
        score += fragmentation * 0.5;
    }

    // Constraint handling: If this is the only bin that can fit the item,
    // prioritize it to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalty for creating a "dead" residual that is too small for any likely item (e.g., < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic classes logic: prioritize filling bins to create "clean" residuals (multiples of common item sizes).
    // The objective is to minimize post_residual, while penalizing residuals that are too small to fit future items.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (residuals < 10 are rarely useful given the item range).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Harmonic alignment: favor residuals that are multiples of 20 (common divisors of 100).
    // This creates "bins of 20" which are highly flexible for future items.
    let harmonic_penalty = (post_residual % 20) as f64 * 1.5;
    score += harmonic_penalty;

    // 3. Lookahead integration: adjust score based on whether the next item fits the current post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly.
            score -= (100 - post_residual) as f64 * 0.2;
        } else {
            // Penalty for stranding the next item if this was the last fitting bin.
            if fitting_bins_count == 1 && !is_new_bin {
                score += 30.0;
            }
        }
    }

    // 4. Threshold for opening new bins: 
    // Only open a new bin if the current best fit is extremely poor (post_residual > 40)
    // or if we are nearing the end of the stream and need to consolidate.
    if is_new_bin {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average residual is already high, 
            // otherwise force utilization of existing space.
            score = 40.0 + (mean_residual * 0.5);
        }
    }

    // 5. Dynamic scaling based on stream progression.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (progress * 0.5);

    score
