        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 2.5;
    }

    // 3. Mean Residual Balancing: If this bin's post_residual is significantly 
    // better than the current average, prioritize it.
    if post_residual < mean_residual as u32 {
        score -= (mean_residual - post_residual as f64) * 1.2;
    }

    // 4. Scarcity Logic: If this is the last bin that can fit the item, 
    // we penalize it to force the use of other bins first, preserving this 
    // "last resort" for when no other options exist.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 40.0;
    }

    // 5. New Bin Aversion: Heavily penalize opening a new bin unless 
    // the current bin's post_residual is extremely poor (e.g., > 60).
