pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating "fragmented" space (small remainders) that are unlikely to fit future items.
    // As progress increases, we become more conservative about creating small residuals.
    let fragmentation_penalty = if post_residual > 0 && post_residual < 15 {
        (15.0 - post_res) * (1.0 + progress * 2.0)
    } else {
        0.0
    };

    // Reward placing items into bins that bring the residual closer to the mean_residual
    // to maintain uniformity across bins, but prioritize Best-Fit (minimizing post_res).
    let alignment_bonus = (post_res - mean_residual).abs() * 0.1;

    // Lookahead: if the next item is large, avoid leaving a residual that is just barely 
    // too small for it.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // If this is the only bin that fits, we should take it unless the residual is 
    // extremely poor (creating a new bin is better).
    let desperation_factor = if fitting_bins_count == 1 && post_residual < 5 {
        -50.0 // Strong incentive to use the last fitting bin
    } else {
        0.0
    };

    // Base score is the residual itself (Best-Fit logic).
    // We add the non-linear penalties and subtract the alignment/desperation bonuses.
    let mut score = post_res + fragmentation_penalty + lookahead_penalty + alignment_bonus + desperation_factor;

    // Special case for opening a new bin (bin_residual == bin_capacity).
    // Only open a new bin if the best existing fit is significantly worse than a fresh start.
    if bin_residual == bin_capacity {
        // As the stream progresses, opening new bins becomes increasingly expensive.
        score = 25.0 + (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (small unusable residuals)
    // We heavily penalize residuals that are too small to fit the average item (assume ~40)
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 5.0;
    }

    // 2. Aggressive 2-step lookahead matching
    // If the next item fits perfectly into the post_residual, prioritize this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave exactly enough for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalize if the next item won't fit here
            score += 15.0;
        }
    }

    // 3. Dynamic adjustment based on current bin state
    // If this is a new bin, apply a base penalty to favor using existing bins
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // 4. Global state awareness
    // If we have many open bins, prioritize filling them to reduce fragmentation
    // If fitting_bins_count is 1, it's a "last chance" bin; prioritize using it to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // 5. Balance against mean residual
    // Reward bins that move the post_residual closer to the current mean_residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base score: prioritize smaller post-residual (Best Fit principle)
    // We penalize larger remaining space to minimize fragmentation.
    let mut score = post.powf(1.5);

    // Encourage keeping bins tight as the stream progresses (dynamic packing density)
    // As we approach the end of the stream, we become increasingly aggressive about
    // filling existing bins to avoid opening new ones unnecessarily.
    let tightness_penalty = (1.0 - progress) * (mean_residual - post).abs();
    score += tightness_penalty;

    // Lookahead logic: if the next item is large and the current post-residual
    // is too small to accommodate it, penalize this bin to save it for a better fit.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 2.0;
        }
    }

    // New bin logic:
    // If the bin is empty (new bin candidate), we calibrate the threshold to be
    // higher than a decent fit but lower than a very poor fit.
    if res == bin_capacity as f64 {
        // As the stream progresses, the cost of opening a new bin increases.
        // We only open a new bin if the average fit quality is very poor.
        score = 40.0 + (progress * 60.0) + (mean_residual * 0.5);
    } else {
        // If this is the last chance to fit the item in an existing bin,
        // we reward this selection heavily to prevent opening a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Penalize excessive open bins to favor consolidation
    score += (open_bins_count as f64).sqrt() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalize opening a new bin unless the remaining items are scarce
        // or the current bin configurations are highly inefficient (high mean_residual).
        score = 85.0 + (progress * 20.0) + (mean_residual * 0.5);
    } else {
        // Best-Fit heuristic base: prefer smaller post_residual (tighter fit).
        // Penalty for leaving "dead space" that cannot accommodate the next item (lookahead).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0;
        }

        // Encourage filling bins that are already "half-full" to avoid fragmentation.
        let utilization = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= utilization * 15.0;

        // If this is the last chance for the current item, prioritize placing it
        // even if the fit is suboptimal.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Global state heuristic: if many bins are open, try to consolidate.
        score += (open_bins_count as f64) * 0.5;
    }

    score
}
